import{_ as i,o,c,a5 as n}from"./chunks/framework.CsGesDJn.js";const _=JSON.parse('{"title":"Bàn giao cho EC2 (Tuấn)","description":"","frontmatter":{},"headers":[],"relativePath":"feature/video-edit-claude-container/handoff.md","filePath":"feature/video-edit-claude-container/handoff.md"}'),a={name:"feature/video-edit-claude-container/handoff.md"};function d(t,e,l,r,h,s){return o(),c("div",null,[...e[0]||(e[0]=[n(`<h1 id="ban-giao-cho-ec2-tuan" tabindex="-1">Bàn giao cho EC2 (Tuấn) <a class="header-anchor" href="#ban-giao-cho-ec2-tuan" aria-label="Permalink to &quot;Bàn giao cho EC2 (Tuấn)&quot;">​</a></h1><h2 id="build" tabindex="-1">Build <a class="header-anchor" href="#build" aria-label="Permalink to &quot;Build&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>python scripts/stage_video_edit_context.py --demovideo &lt;đường dẫn DemoVideo&gt;   # chạy trên máy có DemoVideo + Claude Code đã cài plugin hyperframes</span></span>
<span class="line"><span>docker compose -f compose.video-edit.yml build</span></span></code></pre></div><p>Thư mục <code>.video-edit-context/</code> (khoảng 30 MB, không chứa secret) phải có mặt khi build. Có thể build ở máy owner rồi push image lên ECR, EC2 chỉ cần pull.</p><h2 id="bien-moi-truong" tabindex="-1">Biến môi trường <a class="header-anchor" href="#bien-moi-truong" aria-label="Permalink to &quot;Biến môi trường&quot;">​</a></h2><p>Container đọc chung file <code>.env</code> của ai-service (xem <code>.env.example</code>, phần &quot;Video-edit container&quot;). Compose tự ghi đè các đường dẫn chỉ có trên máy (Windows, 127.0.0.1). Biến cần có:</p><ul><li><code>INTERNAL_SERVICE_KEY</code>, <code>VIDEO_EDIT_MONGO_URI</code>, <code>VIDEO_EDIT_UPLOAD_ORIGINS</code>, <code>VIDEO_EDIT_STORAGE_HOSTS</code></li><li><code>CLAUDE_CODE_OAUTH_TOKEN</code>: cùng token với ai-service, lấy từ SSM <code>/brandhub/ai-service/CLAUDE_CODE_OAUTH_TOKEN</code></li><li><code>VIDEO_EDIT_CONTAINER_MONGO_DATABASE</code>: database riêng, không dùng chung với worker khác</li><li><code>VIDEO_EDIT_CONTAINER_BUSINESS_URL</code>: URL nội bộ của business-service tính từ EC2 mới</li><li><code>VIDEO_EDIT_CONTAINER_ASR_MODEL_DIR</code>: thư mục model ASR trên máy chủ</li><li><code>VIDEO_EDIT_CONTAINER_UPLOAD_REWRITE</code>: để trống trên EC2</li><li>ai-service phải trỏ <code>VIDEO_EDIT_RUNTIME_URL</code> tới worker này</li></ul><h2 id="tai-nguyen" tabindex="-1">Tài nguyên <a class="header-anchor" href="#tai-nguyen" aria-label="Permalink to &quot;Tài nguyên&quot;">​</a></h2><ul><li><code>mem_limit</code> mặc định 6g (<code>VIDEO_EDIT_MEM_LIMIT</code>), 4 CPU (<code>VIDEO_EDIT_CPUS</code>). Chrome + ffmpeg + Claude chạy cùng lúc.</li><li>Volume: <code>video-edit-scratch</code> (clip/thành phẩm), <code>video-edit-claude</code> (session Claude để chat nối tiếp), <code>video-edit-cache</code>.</li><li>Model ASR mount vào <code>/models/asr</code> (<code>VIDEO_EDIT_HOST_MODEL_DIR</code>).</li><li>Nâng phiên bản Claude CLI: sửa phiên bản trong Dockerfile rồi build lại (auto-update đã tắt).</li></ul><h2 id="luu-y-khi-dung-ec2" tabindex="-1">Lưu ý khi dựng EC2 <a class="header-anchor" href="#luu-y-khi-dung-ec2" aria-label="Permalink to &quot;Lưu ý khi dựng EC2&quot;">​</a></h2><ul><li>Đặt <code>VIDEO_EDIT_CONTAINER_MONGO_DATABASE</code> riêng cho worker này, không dùng chung DB với worker khác.</li><li>Để trống <code>VIDEO_EDIT_CONTAINER_UPLOAD_REWRITE</code> khi business trả URL upload công khai hoặc S3.</li><li>Nếu tải clip từ S3 về business chậm hơn 30 giây, đặt <code>spring.mvc.async.request-timeout</code> (ví dụ 10m) cho business.</li></ul>`,11)])])}const E=i(a,[["render",d]]);export{_ as __pageData,E as default};
